function findMaxLength(nums) {
  const first = new Map([[0, -1]]);                  // balance -> first index it appeared
  let balance = 0, best = 0;
  for (let i = 0; i < nums.length; i++) {
    balance += nums[i] === 1 ? 1 : -1;                // a 0 counts as -1
    if (first.has(balance)) {
      best = Math.max(best, i - first.get(balance));  // same balance: equal 0s and 1s between
    } else {
      first.set(balance, i);
    }
  }
  return best;
}

def find_max_length(nums):
    first = {0: -1}                              # balance -> first index it appeared
    balance = best = 0
    for i, x in enumerate(nums):
        balance += 1 if x == 1 else -1           # a 0 counts as -1
        if balance in first:
            best = max(best, i - first[balance]) # same balance: equal 0s and 1s between
        else:
            first[balance] = i
    return best

int findMaxLength(int[] nums) {
    Map<Integer, Integer> first = new HashMap<>();      // balance -> first index it appeared
    first.put(0, -1);
    int balance = 0, best = 0;
    for (int i = 0; i < nums.length; i++) {
        balance += nums[i] == 1 ? 1 : -1;               // a 0 counts as -1
        if (first.containsKey(balance)) {
            best = Math.max(best, i - first.get(balance));   // same balance: equal 0s and 1s between
        } else {
            first.put(balance, i);
        }
    }
    return best;
}

int findMaxLength(vector<int>& nums) {
    unordered_map<int, int> first{{0, -1}};            // balance -> first index it appeared
    int balance = 0, best = 0;
    for (int i = 0; i < (int)nums.size(); i++) {
        balance += nums[i] == 1 ? 1 : -1;               // a 0 counts as -1
        auto it = first.find(balance);
        if (it != first.end()) {
            best = max(best, i - it->second);           // same balance: equal 0s and 1s between
        } else {
            first[balance] = i;
        }
    }
    return best;
}
